import React, { useState, useMemo, useEffect, useReducer, useRef } from "react";
import { App as CapacitorApp } from "@capacitor/app";
import { getData, subscribe } from "./data/dataSource";
import { Home, Shield, Users, CalendarDays, ChevronLeft, ChevronRight, Search, MoreHorizontal, ExternalLink } from "lucide-react";

// ============================================================================
// DATA — generated by scripts/build_data.py from the project CSVs.
// In the real app this arrives from /v1/* endpoints and is cached in IndexedDB.
// Compact array form to keep payload small: same shape the API would return
// after denormalisation (team colour/name baked in, no client-side joins).
// ============================================================================

// Bio: height / age / experience / jersey / position, straight from dim_players.
// Already in the model, previously unused. Coverage is 93-100% except weight
// (53%), which is dropped rather than rendered as a gap. College, draft and
// honours are NOT in wehoop — those need Wikidata (CC0) and land as optional.

// Team bio derived from dim_games home fixtures: primary arena, any alternate
// venues, and mean attendance over games that have reported it. No new source.
// College/founded/coach would come from Wikidata (CC0) and slot in alongside.

// Shot fingerprint, computed from fact_pbp (23,867 FG attempts with zone+result).
// Validated: per-player pbp shot counts reconcile exactly against
// fact_player_box FGA — league total off by 1 in 23,866. LG = league baselines.
// Only players with 60+ FGA; below that a five-way zone split is noise.

// Data is generated by scripts/build_data.py from data/csv/*.csv.
// Never hand-edit src/data/app-data.json — regenerate with `npm run data`.
// Derived tables are `let`, not const, and (re)built by computeTables() so a
// fresher snapshot arriving mid-session swaps the whole app's data with one
// re-render. Components read these module bindings at render time, so
// reassigning them here is all that's needed — no prop/context threading.
let RAW, BIO, TEAM_BIO, SHOTS, GAMEBOX, GAMELINE, TEAMS, TEAM, STANDINGS, PLAYERS, GAMES, GAME, NEWS;
function computeTables() {
  RAW = getData();
  BIO = RAW.BIO || {};
  TEAM_BIO = RAW.TEAM_BIO || {};
  SHOTS = RAW.SHOTS || { LG: null, P: {} };   // null when fact_pbp is absent
  GAMEBOX = RAW.GB || {};                      // per-game box detail, keyed by game id (completed games)
  GAMELINE = RAW.GL || {};                     // per-quarter scores, keyed by game id (reconciled to final)
  // Season-by-season history, keyed by id. Absent until the historical backfill
  // runs (scripts/backfill_history.R) — every history view degrades to "not yet".
  const PHIST = RAW.PHIST || {}, THIST = RAW.THIST || {};
  const hist = (m, id) => m[id] || m[String(id)] || [];
  TEAMS = RAW.T.map(([id, abbr, name, shortName, color, conf]) => ({ id, abbr, name, shortName, color, conf, bio: TEAM_BIO[id] || {}, hist: hist(THIST, id) }));
  TEAM = Object.fromEntries(TEAMS.map(t => [t.id, t]));
  STANDINGS = RAW.S.map(([id, w, l, pct, pf, pa, diff, streak, l10, home, road]) =>
    ({ id, w, l, pct, pf, pa, diff, streak, l10, home, road, ...TEAM[id] }));
  PLAYERS = RAW.P.map(([id, name, teamId, pos, gp, mpg, ppg, rpg, apg, spg, bpg, topg, fg, tp, ft, ts, usg, tpa]) =>
    ({ id, name, teamId, pos, gp, mpg, ppg, rpg, apg, spg, bpg, topg, fg, tp, ft, ts, usg, tpa, team: TEAM[teamId], bio: BIO[id] || {}, hist: hist(PHIST, id) }));
  // iso (element 10) is the tip-off as a UTC timestamp when the feed has a real
  // time; absent on older snapshots and TBD fixtures. Rendered in local time.
  GAMES = RAW.G.map(([id, date, homeId, awayId, hs, as_, net, tier, city, done, iso]) =>
    ({ id, date, homeId, awayId, hs, as: as_, net, tier, city, done: !!done, iso: iso || "", home: TEAM[homeId], away: TEAM[awayId] }));
  GAME = Object.fromEntries(GAMES.map(g => [g.id, g]));
  // link is optional (older/preserved snapshots omit it) — the Wire renders a
  // plain, non-clickable headline when it's absent. Never fabricate one.
  NEWS = RAW.N.map(([headline, byline, abbr, date, link]) => ({ headline, byline, abbr, date, link: link || "" }));
}
computeTables();

// ---- theme -------------------------------------------------------------------
// LIGHT = "Chalk Court" (the agate newspaper look). DARK = "Report Palette", a
// broadcast-dark scheme. Same token keys so every screen themes for free; onRule
// is the text colour that sits on a rule-coloured (selected) chip.
const LIGHT = {
  page: "#F4F2EC", card: "#ECEAE2", visual: "#FFFFFF", stripe: "#F7F6F1",
  border: "#DEDBD2", rule: "#15151C", text: "#15151C", sec: "#5B6472",
  mute: "#8A8F98", accent: "#FE5000", good: "#1E8F5E", bad: "#C23934", blue: "#3B6FC4",
  onRule: "#FFFFFF",
};
const DARK = {
  page: "#15151C", card: "#1F1F29", visual: "#1F1F29", stripe: "#2A2A36",
  border: "#33333F", rule: "#F4F2EC", text: "#F4F2EC", sec: "#8B93A5",
  mute: "#6E7683", accent: "#FE5000", good: "#2FA872", bad: "#D9534F", blue: "#4C8DE8",
  onRule: "#15151C",
};
const DISPLAY = "'Oswald', sans-serif";
const BODY = "'Roboto', system-ui, sans-serif";
const agate = { fontVariantNumeric: "tabular-nums", fontFeatureSettings: "'tnum'" };

// C, thStyle and tdStyle are reassigned by applyTheme() so switching mode
// re-themes the whole app on the next render (everything reads them at render time).
const THEME_KEY = "courtside:theme";
let C = LIGHT, thStyle, tdStyle;
function applyTheme(mode) {
  C = mode === "dark" ? DARK : LIGHT;
  thStyle = { fontSize: 8.5, letterSpacing: .8, textTransform: "uppercase", color: C.sec, fontWeight: 700, padding: "5px 0 4px", borderBottom: `1px solid ${C.border}`, textAlign: "right" };
  tdStyle = { fontSize: 11.5, padding: "6px 0", textAlign: "right", color: C.text, ...agate };
  if (typeof document !== "undefined") {
    document.body.style.background = C.page;
    document.documentElement.style.colorScheme = mode === "dark" ? "dark" : "light";
  }
}
function initialTheme() {
  try { return localStorage.getItem(THEME_KEY) === "dark" ? "dark" : "light"; } catch { return "light"; }
}
applyTheme(initialTheme());

// ---- ASSET LAYER ------------------------------------------------------------
// Team crests and player faces are three separate rights (trademark on the mark,
// copyright on the photo, right of publicity on the likeness) and NO data
// provider licenses them for the WNBA today. So imagery is a *slot*: if a
// licensed URL exists we render it, otherwise we render a typographic fallback
// that is ours outright and ships legally as-is.
//
// To switch on real assets later, populate these resolvers with your own CDN
// (never hot-link a third party's) and everything downstream just works.
const ASSETS = {
  crestUrl: (_team) => null,   // e.g. t => `https://cdn.yourdomain/crests/${t.abbr}.svg`
  faceUrl: (_player) => null,  // e.g. p => `https://cdn.yourdomain/faces/${p.id}.webp`
};

// Several club colours are near-white (POR #cee5eb, LV #a7a8aa). Picking text
// colour by luminance rather than assuming white keeps every crest legible.
function readableOn(hex) {
  const h = hex.replace("#", "");
  const [r, g, b] = [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) / 255);
  const lin = (c) => (c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4));
  const L = 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
  return L > 0.45 ? C.text : "#FFFFFF";
}

// Letterpress monogram — the club's own colour and letters, set like an agate
// page would. Recognisable at 20px, which a detailed crest never is.
function Crest({ team, size = 30 }) {
  const url = ASSETS.crestUrl(team);
  if (url) return <img src={url} alt="" width={size} height={size} style={{ display: "block", objectFit: "contain", flexShrink: 0 }} />;
  const fg = readableOn(team.color);
  return (
    <div aria-hidden style={{
      width: size, height: size, background: team.color, flexShrink: 0,
      display: "flex", alignItems: "center", justifyContent: "center",
      borderRadius: 2, border: `1px solid rgba(21,21,28,.14)`,
    }}>
      <span style={{
        fontFamily: DISPLAY, fontWeight: 700, color: fg,
        fontSize: size * 0.4, letterSpacing: size * 0.012, lineHeight: 1,
      }}>{team.abbr}</span>
    </div>
  );
}

function Face({ player, size = 44 }) {
  const url = ASSETS.faceUrl(player);
  const t = player.team;
  if (url) return <img src={url} alt="" width={size} height={size} style={{ display: "block", borderRadius: 99, objectFit: "cover", flexShrink: 0, border: `2px solid ${t.color}` }} />;
  const initials = player.name.split(" ").map(w => w[0]).slice(0, 2).join("");
  const fg = readableOn(t.color);
  return (
    <div aria-hidden style={{
      width: size, height: size, borderRadius: 99, background: t.color, flexShrink: 0,
      display: "flex", alignItems: "center", justifyContent: "center", border: `1px solid rgba(21,21,28,.14)`,
    }}>
      <span style={{ fontFamily: DISPLAY, fontWeight: 600, color: fg, fontSize: size * 0.36, letterSpacing: .5 }}>{initials}</span>
    </div>
  );
}


// percentile among positional peers with >= 8 GP — mirrors the report's
// Selected Player Percentile DAX pattern
function percentile(player, key, higherIsBetter = true) {
  const peers = PLAYERS.filter(p => p.pos === player.pos && p.gp >= 8);
  if (!peers.length) return 0;
  const below = peers.filter(p => (higherIsBetter ? p[key] <= player[key] : p[key] >= player[key])).length;
  return Math.round((below / peers.length) * 100);
}

const fmtDate = (iso) => {
  const d = new Date(iso + "T12:00:00");
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric" }).toUpperCase();
};

// Tip-off in the viewer's own timezone. `iso` is a UTC timestamp from the feed;
// returns "" when it's absent (older snapshots / TBD fixtures) so the caller
// simply renders nothing rather than a fabricated time.
const fmtLocalTime = (iso) => {
  if (!iso) return "";
  const d = new Date(iso);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
};

export default function CourtsideApp() {
  const [tab, setTab] = useState("home");
  const [stack, setStack] = useState(null); // {type:'team'|'player', id}
  const [search, setSearch] = useState(false);
  const [theme, setTheme] = useState(initialTheme());
  const chooseTheme = (m) => { applyTheme(m); try { localStorage.setItem(THEME_KEY, m); } catch {} setTheme(m); };
  const [ready, setReady] = useState(false); // drives the splash fade-out
  const [showExit, setShowExit] = useState(false); // exit-confirm dialog on the Android back button

  // Android hardware/gesture back button. One level per press:
  //   exit dialog open ▸ close it   ·   search open ▸ close it
  //   detail page open ▸ pop to the tab   ·   on a top-level tab ▸ ask to exit
  // A ref holds the latest state so the once-registered native listener always
  // sees current values without re-subscribing.
  const backRef = useRef(() => {});
  backRef.current = () => {
    if (showExit) { setShowExit(false); return; }
    if (search)   { setSearch(false);  return; }
    if (stack)    { setStack(null);    return; }
    setShowExit(true);
  };
  useEffect(() => {
    let handle;
    // Registering a backButton listener overrides Capacitor's default (exit the
    // app), so navigation is ours to drive. No-op on web (event never fires).
    CapacitorApp.addListener?.("backButton", () => backRef.current())
      .then(h => { handle = h; }).catch(() => {});
    // Mirror of the same handler for headless testing (no hardware button on web).
    if (typeof window !== "undefined") window.__courtsideBack = () => backRef.current();
    return () => { try { handle && handle.remove(); } catch {} };
  }, []);
  const exitApp = () => { try { CapacitorApp.exitApp?.(); } catch {} };

  // Live data refresh (Phase 2): when a fresher snapshot arrives from the
  // network, rebuild the derived tables and re-render — no relaunch needed.
  const [, bumpData] = useReducer((x) => x + 1, 0);
  useEffect(() => subscribe(() => { computeTables(); bumpData(); }), []);

  // Hold the brand splash briefly, then fade into the app. (When we move to
  // fetch-at-runtime, flip `ready` after the data resolves instead of a timer.)
  useEffect(() => {
    const t = setTimeout(() => setReady(true), 1100);
    return () => clearTimeout(t);
  }, []);

  const open = (type, id) => { setSearch(false); setStack({ type, id }); };
  const back = () => setStack(null);
  // Headless-testing hook, matching window.__courtsideBack above: lets a screenshot
  // harness jump straight to a team/player/game page (no hardware nav on web).
  if (typeof window !== "undefined") window.__courtsideOpen = open;

  return (
    <div style={{ background: C.page, color: C.text, height: "100%", display: "flex", flexDirection: "column", position: "relative", overflow: "hidden", fontFamily: BODY }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Roboto:wght@400;500;700&display=swap');
        .noscroll::-webkit-scrollbar{display:none}
        .noscroll{scrollbar-width:none}
        @media (prefers-reduced-motion: reduce){*{transition:none!important}}
      `}</style>

      <Splash done={ready} />

      {search && <SearchOverlay open={open} close={() => setSearch(false)} />}

      {showExit && <ExitConfirm onCancel={() => setShowExit(false)} onExit={exitApp} />}

      {stack ? (
        stack.type === "team"
          ? <TeamDetail team={TEAM[stack.id]} onBack={back} openPlayer={(id) => open("player", id)} openGame={(id) => open("game", id)} />
          : stack.type === "game"
            ? <GameDetail game={GAME[stack.id]} onBack={back} openTeam={(id) => open("team", id)} openPlayer={(id) => open("player", id)} openGame={(id) => open("game", id)} />
            : <PlayerDetail player={PLAYERS.find(p => p.id === stack.id)} onBack={back} openTeam={(id) => open("team", id)} />
      ) : (
        <>
          {tab === "home" && <HomeScreen open={open} onSearch={() => setSearch(true)} />}
          {tab === "teams" && <TeamsScreen open={open} onSearch={() => setSearch(true)} />}
          {tab === "players" && <PlayersScreen open={open} />}
          {tab === "schedule" && <ScheduleScreen open={open} />}
          {tab === "more" && <MoreScreen theme={theme} setTheme={chooseTheme} />}
        </>
      )}

      <TabBar tab={tab} setTab={(t) => { setStack(null); setTab(t); }} />
    </div>
  );
}

// Launch splash. Same cream background + Courtside mark as the native splash
// (capacitor.config.json), so the native → web handoff is seamless. `done`
// fades it out to reveal the app; it stays mounted (just transparent) so it
// can be reused as a data-loading gate once we move to fetch-at-runtime.
function Splash({ done }) {
  return (
    <div aria-hidden style={{
      position: "absolute", inset: 0, zIndex: 60, background: C.page,
      display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
      opacity: done ? 0 : 1, pointerEvents: done ? "none" : "auto",
      transition: "opacity .5s ease",
    }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        {/* Generic basketball, our own vector — no third-party marks (CLAUDE.md → Imagery). */}
        <svg width="28" height="28" viewBox="0 0 100 100" aria-hidden style={{ flexShrink: 0, display: "block" }}>
          <circle cx="50" cy="50" r="46" fill={C.accent} stroke={C.rule} strokeWidth="4" />
          <g fill="none" stroke={C.rule} strokeWidth="4.5" strokeLinecap="round">
            <path d="M50 5 V95" />
            <path d="M5 50 H95" />
            <path d="M50 5 C 20 27 20 73 50 95" />
            <path d="M50 5 C 80 27 80 73 50 95" />
          </g>
        </svg>
        <span style={{ fontFamily: DISPLAY, fontSize: 37, fontWeight: 600, letterSpacing: 2.5, textTransform: "uppercase", color: C.text, lineHeight: 1 }}>Courtside</span>
      </div>
      <span style={{ width: 132, height: 1.5, background: C.rule, marginTop: 16, opacity: .85 }} />
      <span style={{ marginTop: 12, fontSize: 10, letterSpacing: 3.5, textTransform: "uppercase", color: C.sec, fontWeight: 700 }}>WNBA statistics</span>
      <span style={{ position: "absolute", bottom: 30, fontSize: 8.5, letterSpacing: 2, textTransform: "uppercase", color: C.mute, fontWeight: 600 }}>A WNBA Fan Project</span>
    </div>
  );
}

// Exit confirmation, shown when the back button is pressed on a top-level tab.
// Chalk-Court styling (accent spine, agate display type). Tapping the scrim or
// Cancel dismisses; Exit closes the app (App.exitApp — no-op on the web).
function ExitConfirm({ onCancel, onExit }) {
  return (
    <div role="dialog" aria-modal="true" aria-label="Exit Courtside"
      onClick={onCancel}
      style={{ position: "absolute", inset: 0, zIndex: 50, background: "rgba(21,21,28,.55)",
        display: "flex", alignItems: "center", justifyContent: "center", padding: 28 }}>
      <div onClick={e => e.stopPropagation()} style={{
        width: "100%", maxWidth: 300, background: C.card, border: `1px solid ${C.border}`,
        borderRadius: 6, overflow: "hidden", boxShadow: "0 14px 44px rgba(0,0,0,.34)" }}>
        <div style={{ height: 4, background: C.accent }} />
        <div style={{ padding: "18px 18px 16px" }}>
          <div style={{ fontFamily: DISPLAY, fontWeight: 600, fontSize: 17, letterSpacing: .5, textTransform: "uppercase", color: C.text }}>Exit Courtside?</div>
          <p style={{ fontSize: 12.5, lineHeight: 1.5, color: C.sec, margin: "6px 0 16px" }}>You're on the main screen. Close the app?</p>
          <div style={{ display: "flex", gap: 10 }}>
            <button onClick={onCancel} style={{ flex: 1, padding: "10px 0", border: `1px solid ${C.border}`, background: C.visual, color: C.text, borderRadius: 4, fontSize: 12, fontWeight: 700, letterSpacing: .6, textTransform: "uppercase", cursor: "pointer", fontFamily: BODY }}>Stay</button>
            <button onClick={onExit} style={{ flex: 1, padding: "10px 0", border: "none", background: C.rule, color: C.onRule, borderRadius: 4, fontSize: 12, fontWeight: 700, letterSpacing: .6, textTransform: "uppercase", cursor: "pointer", fontFamily: BODY }}>Exit</button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ============================================================================
function Masthead({ title, sub, onSearch }) {
  return (
    <div style={{ padding: "8px 16px 10px", borderBottom: `2px solid ${C.rule}`, display: "flex", alignItems: "flex-end", justifyContent: "space-between" }}>
      <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
        <span style={{ width: 8, height: 8, borderRadius: 99, background: C.accent }} />
        <span style={{ fontFamily: DISPLAY, fontWeight: 700, fontSize: 18, letterSpacing: 1.2, textTransform: "uppercase", color: C.text }}>{title}</span>
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <span style={{ fontSize: 9.5, color: C.sec, letterSpacing: 1, textTransform: "uppercase", fontWeight: 500 }}>{sub}</span>
        {onSearch && <button onClick={onSearch} aria-label="Search" style={{ border: "none", background: "none", padding: 2, cursor: "pointer", display: "flex" }}><Search size={16} color={C.sec} /></button>}
      </div>
    </div>
  );
}

// Global search: players AND teams from any screen. A stats app is a lookup
// tool — making people navigate to a tab before they can type is friction that
// the search-first sports apps all removed years ago.
function SearchOverlay({ open, close }) {
  const [q, setQ] = useState("");
  const hits = useMemo(() => {
    const t = q.trim().toLowerCase();
    if (!t) return { players: [], teams: [] };
    return {
      teams: TEAMS.filter(x => x.name.toLowerCase().includes(t) || x.abbr.toLowerCase() === t).slice(0, 3),
      players: PLAYERS.filter(x => x.name.toLowerCase().includes(t)).slice(0, 12),
    };
  }, [q]);
  const empty = q.trim() && !hits.players.length && !hits.teams.length;
  return (
    <div style={{ position: "absolute", inset: 0, background: C.page, zIndex: 20, display: "flex", flexDirection: "column", borderRadius: 33 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "12px 14px", borderBottom: `2px solid ${C.rule}` }}>
        <Search size={15} color={C.sec} />
        <input autoFocus value={q} onChange={e => setQ(e.target.value)} placeholder="Players and teams"
          style={{ flex: 1, border: "none", outline: "none", background: "none", fontSize: 15, fontFamily: BODY, color: C.text }} />
        <button onClick={close} style={{ border: "none", background: "none", fontSize: 11.5, color: C.sec, cursor: "pointer", fontWeight: 600, letterSpacing: .5, textTransform: "uppercase", fontFamily: BODY }}>Close</button>
      </div>
      <div className="noscroll" style={{ flex: 1, overflowY: "auto", padding: "0 14px 12px" }}>
        {!q.trim() && <div style={{ padding: "26px 0", textAlign: "center", fontSize: 12, color: C.mute, lineHeight: 1.6 }}>Start typing a player or club.<br />Try “Bueckers” or “Lynx”.</div>}
        {empty && <div style={{ padding: "26px 0", textAlign: "center", fontSize: 12.5, color: C.sec }}>Nothing matches “{q}”.<br /><span style={{ fontSize: 11, color: C.mute }}>Players need 5+ games to appear.</span></div>}
        {hits.teams.length > 0 && <SectionHead>Clubs</SectionHead>}
        {hits.teams.map(t => (
          <button key={t.id} onClick={() => open("team", t.id)} style={{ width: "100%", display: "flex", alignItems: "center", gap: 9, padding: "9px 0", border: "none", borderBottom: `1px solid ${C.border}`, background: "none", cursor: "pointer", textAlign: "left" }}>
            <Crest team={t} size={26} />
            <span style={{ flex: 1, fontSize: 13, color: C.text }}>{t.name}</span>
            <ChevronRight size={13} color={C.mute} />
          </button>
        ))}
        {hits.players.length > 0 && <SectionHead>Players</SectionHead>}
        {hits.players.map(p => (
          <button key={p.id} onClick={() => open("player", p.id)} style={{ width: "100%", display: "flex", alignItems: "center", gap: 9, padding: "8px 0", border: "none", borderBottom: `1px solid ${C.border}`, background: "none", cursor: "pointer", textAlign: "left" }}>
            <Face player={p} size={26} />
            <span style={{ flex: 1, fontSize: 12.5, color: C.text }}>{p.name}
              <span style={{ color: C.mute, fontSize: 9.5, marginLeft: 5 }}>{p.team.abbr} · {p.pos}</span></span>
            <span style={{ fontFamily: DISPLAY, fontSize: 13, fontWeight: 600, ...agate, color: C.sec }}>{p.ppg}</span>
          </button>
        ))}
      </div>
    </div>
  );
}

// ---- the score rail: the strip every sports app has, in agate ---------------
function ScoreRail({ open }) {
  const days = useMemo(() => {
    const byDate = {};
    GAMES.forEach(g => { (byDate[g.date] ||= []).push(g); });
    // Latest results first: take the most recent days that have completed games
    // so the rail is current, not stuck on opening week.
    const recent = Object.keys(byDate)
      .filter(d => byDate[d].some(g => g.done))
      .sort()          // ISO dates ascending
      .slice(-6)       // last six days with results
      .reverse();      // newest first
    return recent.map(d => [d, byDate[d].filter(g => g.done)]);
  }, []);
  return (
    <div className="noscroll" style={{ display: "flex", gap: 0, overflowX: "auto", background: C.visual, borderBottom: `1px solid ${C.border}` }}>
      {days.map(([date, gs]) => (
        <div key={date} style={{ borderRight: `1px solid ${C.border}`, flexShrink: 0 }}>
          <div style={{ fontSize: 8.5, letterSpacing: 1, color: C.sec, padding: "5px 10px 3px", fontWeight: 700, textTransform: "uppercase", background: C.stripe }}>{fmtDate(date)}</div>
          <div style={{ display: "flex" }}>
            {gs.map(g => (
              <button key={g.id} onClick={() => open("game", g.id)} style={{ border: "none", background: "none", padding: "6px 10px 8px", borderRight: `1px solid ${C.stripe}`, textAlign: "left", cursor: "pointer" }}>
                <RailSide t={g.away} score={g.as} win={g.done && g.as > g.hs} done={g.done} />
                <RailSide t={g.home} score={g.hs} win={g.done && g.hs > g.as} done={g.done} />
                {!g.done && <div style={{ fontSize: 7.5, color: g.tier === "N" ? C.accent : C.mute, fontWeight: 700, marginTop: 2, letterSpacing: .3 }}>{g.net.replace("WNBA ", "")}</div>}
              </button>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}
function RailSide({ t, score, win, done }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 5, minWidth: 62 }}>
      <span style={{ width: 6, height: 6, borderRadius: 99, background: t.color, flexShrink: 0 }} />
      <span style={{ fontSize: 11, fontWeight: win ? 700 : 400, color: C.text, flex: 1 }}>{t.abbr}</span>
      <span style={{ fontFamily: DISPLAY, fontSize: 12.5, fontWeight: win ? 700 : 400, color: done ? (win ? C.text : C.mute) : C.mute, ...agate }}>{done ? score : "–"}</span>
    </div>
  );
}

// ---- shared agate table primitives -----------------------------------------
function SectionHead({ children, action }) {
  return (
    <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", padding: "14px 0 5px", borderBottom: `1.5px solid ${C.rule}`, marginBottom: 2 }}>
      <span style={{ fontFamily: DISPLAY, fontWeight: 600, fontSize: 13.5, letterSpacing: 1.4, textTransform: "uppercase", color: C.text }}>{children}</span>
      {action && <span style={{ fontSize: 9.5, color: C.sec, letterSpacing: .6, textTransform: "uppercase" }}>{action}</span>}
    </div>
  );
}
// thStyle / tdStyle are defined by applyTheme() above so they re-theme on mode switch.

// A Wire headline. Clickable → opens the ESPN story externally when a link is
// present (Capacitor routes non-allowlisted hosts to the system browser; on the
// web it opens a new tab). Without a link it degrades to a plain headline — we
// never fabricate a URL. The ↗ glyph is the only tap affordance a touch device gets.
function NewsRow({ n }) {
  const head = <div style={{ fontSize: 12.5, fontWeight: 500, lineHeight: 1.35, color: C.text }}>{n.headline}</div>;
  const meta = (
    <div style={{ fontSize: 9.5, color: C.sec, marginTop: 3, letterSpacing: .4, textTransform: "uppercase" }}>
      {n.abbr && <b style={{ color: C.accent }}>{n.abbr} · </b>}{n.byline || "Staff"}
    </div>
  );
  if (!n.link) return <div style={{ padding: "9px 0", borderBottom: `1px solid ${C.border}` }}>{head}{meta}</div>;
  return (
    <a href={n.link} target="_blank" rel="noopener noreferrer"
       style={{ display: "flex", alignItems: "flex-start", gap: 9, padding: "9px 0", borderBottom: `1px solid ${C.border}`, textDecoration: "none" }}>
      <span style={{ flex: 1, minWidth: 0 }}>{head}{meta}</span>
      <ExternalLink size={13} color={C.mute} style={{ flexShrink: 0, marginTop: 2 }} />
    </a>
  );
}

