// ============================================================================
function ScheduleScreen({ open }) {
  const cutoff = RAW.meta.lastGame || "";   // latest final; games dated before this with no result are "awaiting"
  const days = useMemo(() => {
    const m = {};
    // Everything not yet played. A game whose date has passed but has no result
    // (postponed, or the box score is still landing) is kept and marked
    // "Awaiting data" in the row rather than hidden, so nothing silently
    // disappears. It resolves once the result arrives or the feed reschedules it.
    GAMES.filter(g => !g.done)
      .slice()
      .sort((a, b) => a.date < b.date ? -1 : a.date > b.date ? 1 : 0)
      .forEach(g => { (m[g.date] ||= []).push(g); });
    return Object.entries(m);
  }, []);
  const upcoming = days.reduce((n, [, gs]) => n + gs.length, 0);
  const anyTimes = days.some(([, gs]) => gs.some(g => g.iso));
  return (
    <>
      <Masthead title="Schedule" sub={`${upcoming} upcoming${anyTimes ? " · times local" : ""}`} />
      <div className="noscroll" style={{ flex: 1, overflowY: "auto", padding: "0 14px 12px" }}>
        {days.length === 0 && (
          <div style={{ textAlign: "center", color: C.mute, fontSize: 12, padding: "40px 0" }}>
            No upcoming games — the season is complete.
          </div>
        )}
        {days.map(([date, gs]) => (
          <div key={date}>
            <div style={{ fontSize: 9.5, fontWeight: 700, letterSpacing: 1.2, textTransform: "uppercase", color: C.sec, padding: "12px 0 4px", borderBottom: `1.5px solid ${C.rule}` }}>
              {new Date(date + "T12:00:00").toLocaleDateString("en-US", { weekday: "long", month: "short", day: "numeric" })}
            </div>
            {gs.map(g => {
              const awaiting = g.date < cutoff;   // date has passed but no box score yet
              return (
              <div key={g.id} onClick={() => open("game", g.id)} style={{ display: "flex", alignItems: "center", gap: 8, padding: "9px 0", borderBottom: `1px solid ${C.border}`, cursor: "pointer" }}>
                <div style={{ flex: 1 }}>
                  <SchedSide t={g.away} score={g.as} win={g.done && g.as > g.hs} done={g.done} />
                  <SchedSide t={g.home} score={g.hs} win={g.done && g.hs > g.as} done={g.done} prefix="vs" />
                </div>
                <div style={{ textAlign: "right", minWidth: 74 }}>
                  {awaiting
                    ? <div style={{ fontSize: 8.5, fontWeight: 700, letterSpacing: .5, textTransform: "uppercase", color: C.sec, border: `1px solid ${C.border}`, borderRadius: 2, padding: "2px 5px", display: "inline-block" }}>Awaiting data</div>
                    : <>
                        {fmtLocalTime(g.iso) && <div style={{ fontFamily: DISPLAY, fontSize: 13, fontWeight: 600, color: C.text, ...agate }}>{fmtLocalTime(g.iso)}</div>}
                        <div style={{ fontSize: 9, fontWeight: 700, letterSpacing: .5, textTransform: "uppercase", color: g.tier === "N" ? C.accent : C.mute, border: g.tier === "N" ? `1px solid ${C.accent}` : "none", borderRadius: 2, padding: g.tier === "N" ? "2px 5px" : 0, display: "inline-block", marginTop: fmtLocalTime(g.iso) ? 2 : 0 }}>{g.net.replace("WNBA ", "")}</div>
                      </>}
                  <div style={{ fontSize: 9, color: C.mute, marginTop: 3 }}>{g.city}</div>
                </div>
              </div>
            );})}
          </div>
        ))}
      </div>
    </>
  );
}
function SchedSide({ t, score, win, done, prefix }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 7, padding: "1px 0" }}>
      <span style={{ width: 3, height: 12, background: t.color, flexShrink: 0 }} />
      <span style={{ fontSize: 12, fontWeight: win ? 700 : 400, color: C.text, flex: 1 }}>{prefix && <span style={{ color: C.mute, fontSize: 9.5 }}>{prefix} </span>}{t.name}</span>
      <span style={{ fontFamily: DISPLAY, fontSize: 14, fontWeight: win ? 700 : 400, color: done ? (win ? C.text : C.mute) : C.mute, ...agate }}>{done ? score : "–"}</span>
    </div>
  );
}

