// Scoring by quarter. Reconciled server-side (quarters sum to the final on both
// sides, else the game is dropped), so the row totals always match the header
// score. Columns extend to OT when the game went past regulation.
function QuarterScores({ g, line }) {
  const home = line.home || [], away = line.away || [];
  const n = Math.max(home.length, away.length, 4);
  const labels = Array.from({ length: n }, (_, i) =>
    i < 4 ? String(i + 1) : (n - 4 > 1 ? `OT${i - 3}` : "OT"));
  const sum = (a) => a.reduce((s, v) => s + (v || 0), 0);
  const aT = sum(away), hT = sum(home);
  const Row = ({ t, vals, tot, win }) => (
    <tr style={{ borderBottom: `1px solid ${C.border}` }}>
      <td style={{ ...tdStyle, textAlign: "left" }}>
        <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <span style={{ width: 3, height: 13, background: t.color, flexShrink: 0 }} />
          <b style={{ fontWeight: 500 }}>{t.abbr}</b>
        </span>
      </td>
      {labels.map((_, i) => <td key={i} style={{ ...tdStyle, color: C.sec }}>{vals[i] ?? "–"}</td>)}
      <td style={{ ...tdStyle, fontWeight: 700, color: win ? C.text : C.sec }}>{tot}</td>
    </tr>
  );
  return (
    <>
      <SectionHead>By quarter</SectionHead>
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead><tr>
          <th style={{ ...thStyle, textAlign: "left" }}>Team</th>
          {labels.map((l, i) => <th key={i} style={thStyle}>{l}</th>)}
          <th style={thStyle}>T</th>
        </tr></thead>
        <tbody>
          <Row t={g.away} vals={away} tot={aT} win={aT > hT} />
          <Row t={g.home} vals={home} tot={hT} win={hT > aT} />
        </tbody>
      </table>
    </>
  );
}

// Prior meetings between the two clubs, most recent first. Merges the historical
// game log (GHIST — completed PAST seasons, from the backfill) with this season's
// completed meetings (from GAMES), so it degrades to just this season before the
// backfill has run, and renders nothing when the two have never met. Historical
// rows aren't in GAME, so only this season's meetings are clickable.
function HeadToHead({ g, openGame }) {
  const a = g.awayId, h = g.homeId;
  const isPair = (x, y) => (x === a && y === h) || (x === h && y === a);
  const hist = (RAW.GHIST || [])
    .filter(([, hid, aid]) => isPair(hid, aid))
    .map(([date, hid, aid, hs, as_, st]) => ({ date, homeId: hid, awayId: aid, hs, as: as_, po: st === 3, id: null }));
  const cur = GAMES
    .filter(x => x.done && x.id !== g.id && isPair(x.homeId, x.awayId))
    .map(x => ({ date: x.date, homeId: x.homeId, awayId: x.awayId, hs: x.hs, as: x.as, po: false, id: x.id }));
  const all = [...hist, ...cur]
    .filter(m => TEAM[m.homeId] && TEAM[m.awayId])
    .sort((p, q) => p.date < q.date ? 1 : p.date > q.date ? -1 : 0);
  if (!all.length) return null;

  // Series tally between the two clubs across everything shown.
  let hWins = 0, aWins = 0;
  for (const m of all) {
    const winId = m.hs > m.as ? m.homeId : m.awayId;
    if (winId === h) hWins++; else if (winId === a) aWins++;
  }
  const lead = hWins === aWins
    ? `Series tied ${hWins}–${aWins}`
    : `${(hWins > aWins ? g.home : g.away).abbr} lead ${Math.max(hWins, aWins)}–${Math.min(hWins, aWins)}`;
  const yr = (d) => d.slice(0, 4);
  const span = all.length > 1 && yr(all[all.length - 1].date) !== yr(all[0].date)
    ? `${yr(all[all.length - 1].date)}–${yr(all[0].date)}` : yr(all[0].date);
  const shown = all.slice(0, 12);

  return (
    <>
      <SectionHead action={`${all.length} meeting${all.length > 1 ? "s" : ""} · ${span}`}>Head-to-head</SectionHead>
      <div style={{ textAlign: "center", padding: "3px 0 9px" }}>
        <span style={{ fontFamily: DISPLAY, fontSize: 15, fontWeight: 700, letterSpacing: .5, textTransform: "uppercase", color: C.text, ...agate }}>{lead}</span>
      </div>
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <tbody>
          {shown.map((m, i) => {
            const home = TEAM[m.homeId], away = TEAM[m.awayId];
            const homeWon = m.hs > m.as;
            const clickable = m.id != null && openGame;
            return (
              <tr key={(m.id || "h") + i} onClick={clickable ? () => openGame(m.id) : undefined}
                  style={{ background: i % 2 ? C.stripe : "transparent", borderBottom: `1px solid ${C.border}`, cursor: clickable ? "pointer" : "default" }}>
                <td style={{ ...tdStyle, textAlign: "left", color: C.sec, whiteSpace: "nowrap", paddingRight: 6 }}>
                  {new Date(m.date + "T12:00:00").toLocaleDateString("en-US", { month: "short", day: "numeric" })}
                  {" ’" + m.date.slice(2, 4)}
                  {m.po && <span style={{ color: C.accent, fontWeight: 700, marginLeft: 4, fontSize: 8.5, letterSpacing: .5 }}>PO</span>}
                </td>
                <td style={{ ...tdStyle, textAlign: "right", fontWeight: !homeWon ? 700 : 400, color: !homeWon ? C.text : C.sec }}>
                  <span style={{ display: "inline-flex", alignItems: "center", gap: 5, justifyContent: "flex-end" }}>
                    {away.abbr}<span style={{ width: 3, height: 11, background: away.color, flexShrink: 0 }} />
                  </span>
                </td>
                <td style={{ ...tdStyle, textAlign: "center", whiteSpace: "nowrap", width: 60 }}>
                  <b style={{ fontWeight: !homeWon ? 700 : 400, color: !homeWon ? C.text : C.sec }}>{m.as}</b>
                  <span style={{ color: C.mute }}>&nbsp;–&nbsp;</span>
                  <b style={{ fontWeight: homeWon ? 700 : 400, color: homeWon ? C.text : C.sec }}>{m.hs}</b>
                </td>
                <td style={{ ...tdStyle, textAlign: "left", fontWeight: homeWon ? 700 : 400, color: homeWon ? C.text : C.sec }}>
                  <span style={{ display: "inline-flex", alignItems: "center", gap: 5 }}>
                    <span style={{ width: 3, height: 11, background: home.color, flexShrink: 0 }} />{home.abbr}
                  </span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      {all.length > shown.length && (
        <div style={{ fontSize: 9.5, color: C.mute, textAlign: "center", padding: "6px 0 0" }}>
          Showing the {shown.length} most recent of {all.length}
        </div>
      )}
    </>
  );
}

// ============================================================================
// Game page. Final score, each club's season form, and — for completed games
// whose box detail is in the bundle (GAMEBOX) — a team box comparison and each
// side's top performers. Recent live-topped games have no box yet and fall back
// to the light view. Everything links through to team and player pages.
function GameDetail({ game: g, onBack, openTeam, openPlayer, openGame }) {
  if (!g || !g.home || !g.away) return null;
  const awaySt = STANDINGS.find(s => s.id === g.awayId) || {};
  const homeSt = STANDINGS.find(s => s.id === g.homeId) || {};
  const awayWin = g.done && g.as > g.hs;
  const homeWin = g.done && g.hs > g.as;
  const dateLabel = new Date(g.date + "T12:00:00").toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric", year: "numeric" });
  const winner = awayWin ? g.away : g.home;
  const gb = GAMEBOX[g.id];   // per-game box detail if present in the snapshot

  const TeamLine = ({ team, st, score, win }) => (
    <button onClick={() => openTeam(team.id)} style={{ width: "100%", display: "flex", alignItems: "center", gap: 11, padding: "13px 4px", border: "none", borderBottom: `1px solid ${C.border}`, background: "none", cursor: "pointer", textAlign: "left" }}>
      <Crest team={team} size={40} />
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontFamily: DISPLAY, fontWeight: 600, fontSize: 15.5, letterSpacing: .3, textTransform: "uppercase", color: C.text, lineHeight: 1.1 }}>{team.name}</div>
        <div style={{ fontSize: 10, color: C.sec, marginTop: 1 }}>{st.w != null ? `${st.w}–${st.l}` : "—"}</div>
      </div>
      {win && <span style={{ fontSize: 8, fontWeight: 700, letterSpacing: .6, color: C.accent, marginRight: 2 }}>WIN</span>}
      <span style={{ fontFamily: DISPLAY, fontSize: 30, fontWeight: 700, color: g.done ? (win ? C.text : C.mute) : C.mute, ...agate }}>{g.done ? score : "–"}</span>
    </button>
  );

  return (
    <>
      <DetailHead color={winner.color} onBack={onBack} eyebrow={g.done ? "Final" : "Upcoming"} title={`${g.away.abbr} @ ${g.home.abbr}`} />
      <div className="noscroll" style={{ flex: 1, overflowY: "auto", padding: "0 14px 16px" }}>
        <div style={{ paddingTop: 4 }}>
          <TeamLine team={g.away} st={awaySt} score={g.as} win={awayWin} />
          <TeamLine team={g.home} st={homeSt} score={g.hs} win={homeWin} />
        </div>

        <div style={{ display: "flex", flexWrap: "wrap", gap: "4px 18px", padding: "12px 2px 2px", fontSize: 11, color: C.sec }}>
          <span style={{ color: C.text, fontWeight: 500 }}>{dateLabel}</span>
          {!g.done && fmtLocalTime(g.iso) && <span style={{ color: C.text, fontWeight: 500 }}>{fmtLocalTime(g.iso)} <span style={{ color: C.mute, fontWeight: 400 }}>local</span></span>}
          {g.city && <span>{g.city}</span>}
          {g.net && <span>{g.net.replace("WNBA ", "")}</span>}
        </div>

        {GAMELINE[g.id] && <QuarterScores g={g} line={GAMELINE[g.id]} />}

        {gb && (() => {
          const A = gb.box.away, H = gb.box.home;   // [pts,reb,ast,stl,blk,tov,fgm,fga,tpm,tpa,ftm,fta]
          const P = (m, a) => a ? Math.round(m / a * 100) : 0;
          // [label, awayText, homeText, awayRank, homeRank] — higher rank is bolded
          // (turnovers pass rank swapped so the LOWER count is the one highlighted).
          const rows = [
            ["FG",  `${A[6]}-${A[7]} (${P(A[6],A[7])}%)`,   `${H[6]}-${H[7]} (${P(H[6],H[7])}%)`,   P(A[6],A[7]),  P(H[6],H[7])],
            ["3PT", `${A[8]}-${A[9]} (${P(A[8],A[9])}%)`,   `${H[8]}-${H[9]} (${P(H[8],H[9])}%)`,   P(A[8],A[9]),  P(H[8],H[9])],
            ["FT",  `${A[10]}-${A[11]} (${P(A[10],A[11])}%)`, `${H[10]}-${H[11]} (${P(H[10],H[11])}%)`, P(A[10],A[11]), P(H[10],H[11])],
            ["REB", A[1], H[1], A[1], H[1]],
            ["AST", A[2], H[2], A[2], H[2]],
            ["STL", A[3], H[3], A[3], H[3]],
            ["BLK", A[4], H[4], A[4], H[4]],
            ["TO",  A[5], H[5], H[5], A[5]],
          ];
          return (
            <>
              <SectionHead>Box score</SectionHead>
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead><tr>
                  <th style={{ ...thStyle, textAlign: "left" }}>{g.away.abbr}</th>
                  <th style={{ ...thStyle, textAlign: "center" }} />
                  <th style={thStyle}>{g.home.abbr}</th>
                </tr></thead>
                <tbody>
                  {rows.map(([k, av, hv, an, hn], i) => (
                    <tr key={k} style={{ background: i % 2 ? C.stripe : "transparent", borderBottom: `1px solid ${C.border}` }}>
                      <td style={{ ...tdStyle, textAlign: "left", fontWeight: an > hn ? 700 : 400, color: an > hn ? C.text : C.sec }}>{av}</td>
                      <td style={{ ...tdStyle, textAlign: "center", fontSize: 8.5, letterSpacing: .8, textTransform: "uppercase", color: C.mute, fontWeight: 700 }}>{k}</td>
                      <td style={{ ...tdStyle, fontWeight: hn > an ? 700 : 400, color: hn > an ? C.text : C.sec }}>{hv}</td>
                    </tr>
                  ))}
                </tbody>
              </table>

              <SectionHead>Top performers</SectionHead>
              {[[g.away, gb.top.away], [g.home, gb.top.home]].map(([t, list]) => (
                <div key={t.id} style={{ paddingTop: 4 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 6, padding: "4px 0 2px" }}>
                    <span style={{ width: 3, height: 12, background: t.color, flexShrink: 0 }} />
                    <span style={{ fontSize: 9.5, fontWeight: 700, letterSpacing: .6, textTransform: "uppercase", color: C.sec }}>{t.name}</span>
                  </div>
                  {(list || []).map(([pid, name, pts, reb, ast]) => {
                    const match = PLAYERS.find(p => String(p.id) === String(pid));
                    return (
                      <button key={pid} disabled={!match} onClick={() => match && openPlayer(match.id)} style={{ width: "100%", display: "flex", alignItems: "center", gap: 8, padding: "7px 0", border: "none", borderBottom: `1px solid ${C.border}`, background: "none", textAlign: "left", cursor: match ? "pointer" : "default" }}>
                        <span style={{ flex: 1, fontSize: 12.5, color: C.text }}>{name}</span>
                        <span style={{ fontFamily: DISPLAY, fontSize: 12.5, ...agate, color: C.sec }}><b style={{ color: C.text }}>{pts}</b> pts · {reb} reb · {ast} ast</span>
                      </button>
                    );
                  })}
                </div>
              ))}
            </>
          );
        })()}

        <SectionHead>Season form</SectionHead>
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead><tr>
            <th style={{ ...thStyle, textAlign: "left" }}>Team</th>
            <th style={thStyle}>REC</th><th style={thStyle}>PF</th><th style={thStyle}>PA</th>
            <th style={thStyle}>STRK</th><th style={thStyle}>L10</th>
          </tr></thead>
          <tbody>
            {[[g.away, awaySt], [g.home, homeSt]].map(([t, st], i) => (
              <tr key={t.id} style={{ background: i % 2 ? C.stripe : "transparent", borderBottom: `1px solid ${C.border}` }}>
                <td style={{ ...tdStyle, textAlign: "left" }}>
                  <span style={{ display: "flex", alignItems: "center", gap: 6 }}>
                    <span style={{ width: 3, height: 13, background: t.color, flexShrink: 0 }} />
                    <b style={{ fontWeight: 500 }}>{t.abbr}</b>
                  </span>
                </td>
                <td style={tdStyle}>{st.w != null ? `${st.w}–${st.l}` : "–"}</td>
                <td style={tdStyle}>{st.pf ?? "–"}</td>
                <td style={tdStyle}>{st.pa ?? "–"}</td>
                <td style={{ ...tdStyle, fontWeight: 700, color: st.streak ? (st.streak[0] === "W" ? C.good : C.bad) : C.mute }}>{st.streak || "–"}</td>
                <td style={tdStyle}>{st.l10 || "–"}</td>
              </tr>
            ))}
          </tbody>
        </table>

        <HeadToHead g={g} openGame={openGame} />

        {(!g.done || !gb) && (
          <div style={{ fontSize: 9.5, color: C.mute, textAlign: "center", padding: "16px 8px 0", lineHeight: 1.5 }}>
            {!g.done ? "Tip-off details. The box score appears here once the game is played."
                     : "Team and player box detail appears here once this game's box score is published."}
          </div>
        )}
      </div>
    </>
  );
}

function SubTabs({ tabs, active, set }) {
  // Four tabs of long words (Percentiles / Fingerprint) crowd at 10.5px, so tighten
  // the type and kill wrapping once there are 4+.
  const tight = tabs.length >= 4;
  return (
    <div style={{ display: "flex", borderBottom: `1px solid ${C.border}`, background: C.visual }}>
      {tabs.map(t => (
        <button key={t} onClick={() => set(t)} style={{
          flex: 1, border: "none", background: "none", padding: "9px 2px", cursor: "pointer", whiteSpace: "nowrap",
          fontSize: tight ? 9.5 : 10.5, fontWeight: 700, letterSpacing: tight ? .2 : .9, textTransform: "uppercase",
          color: active === t ? C.text : C.mute, borderBottom: active === t ? `2.5px solid ${C.accent}` : "2.5px solid transparent", fontFamily: BODY,
        }}>{t}</button>
      ))}
    </div>
  );
}

function TeamDetail({ team, onBack, openPlayer }) {
  const [sub, setSub] = useState("Overview");
  const s = STANDINGS.find(x => x.id === team.id);
  const roster = PLAYERS.filter(p => p.teamId === team.id).sort((a, b) => b.ppg - a.ppg);
  const games = GAMES.filter(g => g.homeId === team.id || g.awayId === team.id);
  const rank = STANDINGS.findIndex(x => x.id === team.id) + 1;

  return (
    <>
      <DetailHead color={team.color} onBack={onBack} badge={<Crest team={team} size={34} />} eyebrow={`${s.conf} · #${rank} league`} title={team.name}
        right={<div style={{ textAlign: "right" }}>
          <div style={{ fontFamily: DISPLAY, fontSize: 21, fontWeight: 700, ...agate }}>{s.w}–{s.l}</div>
          <div style={{ fontSize: 10, fontWeight: 700, color: s.streak[0] === "W" ? C.good : C.bad, ...agate }}>{s.streak}</div>
        </div>} />
      <SubTabs tabs={["Overview", "Roster", "Games", ...(team.hist?.length ? ["History"] : [])]} active={sub} set={setSub} />
      <div className="noscroll" style={{ flex: 1, overflowY: "auto", padding: "0 14px 12px" }}>
        {sub === "Overview" && <>
          <TeamBio team={team} />
          <SectionHead>Season</SectionHead>
          <StatGrid items={[
            ["Win %", s.pct.toFixed(3).replace(/^0/, "")], ["Pts For", s.pf], ["Pts Against", s.pa],
            ["Point Diff", (s.diff > 0 ? "+" : "") + s.diff], ["Home", s.home], ["Road", s.road],
            ["Last 10", s.l10], ["Streak", s.streak],
          ]} />
          <SectionHead action="league avg 86.3">Scoring</SectionHead>
          <Bar label="Points for" v={s.pf} max={95} color={C.blue} />
          <Bar label="Points against" v={s.pa} max={95} color={C.sec} />
          <SectionHead>Top scorers</SectionHead>
          {roster.slice(0, 5).map((p, i) => (
            <button key={p.id} onClick={() => openPlayer(p.id)} style={{ width: "100%", display: "flex", alignItems: "center", gap: 8, padding: "7px 0", border: "none", borderBottom: `1px solid ${C.border}`, background: i % 2 ? C.stripe : "none", cursor: "pointer", textAlign: "left" }}>
              <span style={{ fontSize: 10, color: C.mute, width: 12, ...agate }}>{i + 1}</span>
              <span style={{ flex: 1, fontSize: 12.5 }}>{p.name}<span style={{ color: C.mute, fontSize: 9.5, marginLeft: 4 }}>{p.pos}</span></span>
              <span style={{ fontFamily: DISPLAY, fontSize: 14, fontWeight: 600, ...agate }}>{p.ppg}</span>
            </button>
          ))}
        </>}
        {sub === "Roster" && <>
          <table style={{ width: "100%", borderCollapse: "collapse", marginTop: 6 }}>
            <thead><tr>
              <th style={{ ...thStyle, textAlign: "left" }}>Player</th>
              {["GP", "MPG", "PPG", "REB", "AST", "TS%"].map(h => <th key={h} style={thStyle}>{h}</th>)}
            </tr></thead>
            <tbody>
              {roster.map((p, i) => (
                <tr key={p.id} onClick={() => openPlayer(p.id)} style={{ background: i % 2 ? C.stripe : "transparent", borderBottom: `1px solid ${C.border}`, cursor: "pointer" }}>
                  <td style={{ ...tdStyle, textAlign: "left", fontSize: 11 }}>{p.name}<span style={{ color: C.mute, fontSize: 9, marginLeft: 3 }}>{p.pos}</span></td>
                  <td style={tdStyle}>{p.gp}</td><td style={tdStyle}>{p.mpg}</td>
                  <td style={{ ...tdStyle, fontWeight: 700 }}>{p.ppg}</td>
                  <td style={tdStyle}>{p.rpg}</td><td style={tdStyle}>{p.apg}</td><td style={tdStyle}>{p.ts}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </>}
        {sub === "Games" && <TeamSeason team={team} />}
        {sub === "History" && <TeamHistory team={team} />}
      </div>
    </>
  );
}

function StatGrid({ items }) {
  return (
    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 0, borderTop: `1px solid ${C.border}` }}>
      {items.map(([k, v], i) => (
        <div key={k} style={{ padding: "8px 10px", borderBottom: `1px solid ${C.border}`, borderRight: i % 2 === 0 ? `1px solid ${C.border}` : "none", background: Math.floor(i / 2) % 2 ? C.stripe : "transparent" }}>
          <div style={{ fontSize: 8.5, letterSpacing: .8, textTransform: "uppercase", color: C.sec, fontWeight: 700 }}>{k}</div>
          <div style={{ fontFamily: DISPLAY, fontSize: 17, fontWeight: 600, color: C.text, ...agate }}>{v}</div>
        </div>
      ))}
    </div>
  );
}

function Bar({ label, v, max, color }) {
  return (
    <div style={{ padding: "7px 0", borderBottom: `1px solid ${C.border}` }}>
      <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, color: C.sec, marginBottom: 3 }}>
        <span>{label}</span><b style={{ color: C.text, ...agate }}>{v}</b>
      </div>
      <div style={{ height: 6, background: C.border }}>
        <div style={{ height: "100%", width: `${(v / max) * 100}%`, background: color }} />
      </div>
    </div>
  );
}

function PlayerDetail({ player: p, onBack, openTeam }) {
  const [sub, setSub] = useState("Profile");
  const pcts = [
    ["Points", "ppg", p.ppg, true], ["Rebounds", "rpg", p.rpg, true], ["Assists", "apg", p.apg, true],
    ["True shooting", "ts", p.ts + "%", true], ["Usage", "usg", p.usg + "%", true],
    ["3PT rate", "tpa", p.tpa, true], ["Turnovers", "topg", p.topg, false],
  ];
  return (
    <>
      <DetailHead color={p.team.color} onBack={onBack} badge={<Face player={p} size={38} />} eyebrow={`${p.team.name} · ${p.pos} · ${p.gp} GP`} title={p.name}
        right={<div style={{ textAlign: "right" }}>
          <div style={{ fontFamily: DISPLAY, fontSize: 21, fontWeight: 700, ...agate }}>{p.ppg}</div>
          <div style={{ fontSize: 8.5, color: C.sec, letterSpacing: .8, fontWeight: 700 }}>PPG</div>
        </div>} />
      <SubTabs tabs={["Profile", "Percentiles", "Fingerprint", ...(p.hist?.length ? ["Career"] : [])]} active={sub} set={setSub} />
      <div className="noscroll" style={{ flex: 1, overflowY: "auto", padding: "0 14px 12px" }}>
        {sub === "Profile" && <>
          <BioStrip p={p} />
          <PlayerBlurb p={p} />
          <SectionHead action="per game">Season</SectionHead>
          <StatGrid items={[
            ["Minutes", p.mpg], ["Points", p.ppg], ["Rebounds", p.rpg], ["Assists", p.apg],
            ["Steals", p.spg], ["Blocks", p.bpg], ["Turnovers", p.topg], ["Usage", p.usg + "%"],
          ]} />
          <SectionHead>Team</SectionHead>
          <button onClick={() => openTeam(p.teamId)} style={{ width: "100%", display: "flex", alignItems: "center", gap: 10, padding: "12px 0", border: "none", borderBottom: `1px solid ${C.border}`, background: "none", cursor: "pointer", textAlign: "left" }}>
            <Crest team={p.team} size={30} />
            <span style={{ flex: 1, fontFamily: DISPLAY, fontSize: 14.5, letterSpacing: .5, textTransform: "uppercase" }}>{p.team.name}</span>
            <ChevronLeft size={15} color={C.mute} style={{ transform: "rotate(180deg)" }} />
          </button>
        </>}
        {sub === "Percentiles" && <>
          <SectionHead action={`vs ${p.pos} · min 8 GP`}>Peer rank</SectionHead>
          {pcts.map(([label, key, val, hib]) => {
            const pc = percentile(p, key, hib);
            return (
              <div key={key} style={{ padding: "9px 0", borderBottom: `1px solid ${C.border}` }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 4 }}>
                  <span style={{ fontSize: 11.5, color: C.sec }}>{label}</span>
                  <span style={{ fontSize: 11.5, ...agate }}>
                    <b style={{ color: C.text }}>{val}</b>
                    <span style={{ color: pc >= 75 ? C.good : pc <= 25 ? C.bad : C.mute, marginLeft: 7, fontWeight: 700 }}>{pc}th</span>
                  </span>
                </div>
                <div style={{ height: 7, background: C.border, position: "relative" }}>
                  <div style={{ height: "100%", width: `${pc}%`, background: pc >= 75 ? C.blue : pc <= 25 ? C.bad : C.sec }} />
                  <div style={{ position: "absolute", left: "50%", top: -2, bottom: -2, width: 1, background: C.rule, opacity: .35 }} />
                </div>
              </div>
            );
          })}
          <div style={{ fontSize: 9, color: C.mute, paddingTop: 8, lineHeight: 1.5 }}>
            Percentile vs. same-position players with 8+ games. Centre rule marks the positional median. Turnovers inverted — lower is better.
          </div>
        </>}
        {sub === "Fingerprint" && <ShotFingerprint p={p} />}
        {sub === "Career" && <CareerArc p={p} />}
      </div>
    </>
  );
}

// ============================================================================
// More / Support. No ads — so this is where the tip jar lives, alongside the
// attribution and data-source disclosure the store listing needs anyway.
// Deliberately the last tab: it should be findable, never in the way.
function MoreScreen({ theme, setTheme }) {
  return (
    <>
      <Masthead title="About" sub="sources · credits" />
      <div className="noscroll" style={{ flex: 1, overflowY: "auto", padding: "0 14px 16px" }}>

        <SectionHead>Appearance</SectionHead>
        <div style={{ display: "flex", gap: 0, margin: "8px 0 2px", border: `1px solid ${C.border}`, borderRadius: 3, overflow: "hidden" }}>
          {[["light", "Light"], ["dark", "Dark"]].map(([k, label]) => (
            <button key={k} onClick={() => setTheme(k)} style={{
              flex: 1, border: "none", padding: "8px 0", fontSize: 11, fontWeight: 700, letterSpacing: .8, textTransform: "uppercase",
              background: theme === k ? C.rule : C.visual, color: theme === k ? C.onRule : C.sec, cursor: "pointer", fontFamily: BODY,
            }}>{label}</button>
          ))}
        </div>
        <p style={{ fontSize: 10.5, lineHeight: 1.5, color: C.mute, padding: "6px 0 0", margin: 0 }}>
          Light is the newspaper “Chalk Court” look; dark is the broadcast “Report” palette. Your choice is remembered.
        </p>

        <SectionHead>Where the numbers come from</SectionHead>
        <p style={{ fontSize: 11.5, lineHeight: 1.6, color: C.sec, padding: "8px 0 4px", margin: 0 }}>
          Every stat is built from the <b style={{ color: C.text }}>wehoop</b> R package — part of the{" "}
          <b style={{ color: C.text }}>SportsDataverse</b> — which draws women's basketball data from
          ESPN and the WNBA Stats API. wehoop is released under the MIT License and used here with
          attribution, exactly as its authors request:
        </p>
        <Cite text="Saiem Gilani and Geoff Hutchinson. wehoop: The SportsDataverse's R Package for Women's Basketball Data. Retrieved from https://doi.org/10.32614/CRAN.package.wehoop" />
        <Cite text="Saiem Gilani. sportsdataverse: The Set of R Packages for Sports Data. Retrieved from https://r.sportsdataverse.org" />

        <SectionHead>How to read this</SectionHead>
        <p style={{ fontSize: 11.5, lineHeight: 1.6, color: C.sec, padding: "8px 0 0", margin: 0 }}>
          Percentiles compare a player against others at the same position with eight or more games.
          Usage rate is an estimate and isn't adjusted for team pace. A game counts as final once its
          box score lands, which can trail the schedule by a few hours.
        </p>

        <SectionHead>Credits</SectionHead>
        <p style={{ fontSize: 11.5, lineHeight: 1.6, color: C.sec, padding: "8px 0 0", margin: 0 }}>
          Courtside is a free, independent project. No ads, no tracking, no accounts.
          It isn't affiliated with, endorsed by, or connected to the WNBA or any of its clubs.
          Club names and abbreviations identify whose results are shown, nothing more.
        </p>
      </div>
    </>
  );
}

// Verbatim attribution block for a data source. Plain selectable text (not a
// link) so it renders identically in the browser and over file:// on device.
// The 3px spine is an accent use, never a data-series colour (see CLAUDE.md).
function Cite({ text }) {
  return (
    <div style={{ display: "flex", gap: 9, padding: "9px 0", borderBottom: `1px solid ${C.border}` }}>
      <span style={{ width: 3, background: C.accent, flexShrink: 0, borderRadius: 1 }} />
      <p style={{ margin: 0, fontSize: 11, lineHeight: 1.55, color: C.sec, wordBreak: "break-word" }}>{text}</p>
    </div>
  );
}


// Bio facts from dim_players. Every field is optional — Wikidata-sourced
// college/honours will be patchy for rookies and international players, so the
// strip has to degrade rather than leave holes.
function BioStrip({ p }) {
  const b = p.bio || {};
  const facts = [
    b.no && ["No.", b.no],
    b.posFull && ["Position", b.posFull],
    b.h && ["Height", b.h],
    b.age && ["Age", b.age],
    b.exp != null && ["Experience", b.exp === 0 ? "Rookie" : `${b.exp} yr${b.exp > 1 ? "s" : ""}`],
    b.college && ["College", b.college],   // Wikidata (CC0) — see scripts/wikidata_bio.py
  ].filter(Boolean);
  if (!facts.length) return null;
  return (
    <div className="noscroll" style={{ display: "flex", gap: 0, overflowX: "auto", borderBottom: `1px solid ${C.border}`, marginTop: 2 }}>
      {facts.map(([k, v], i) => (
        <div key={k} style={{ padding: "9px 13px 9px 0", marginRight: 13, borderRight: i < facts.length - 1 ? `1px solid ${C.border}` : "none", flexShrink: 0 }}>
          <div style={{ fontSize: 8, letterSpacing: .9, textTransform: "uppercase", color: C.sec, fontWeight: 700 }}>{k}</div>
          <div style={{ fontFamily: DISPLAY, fontSize: 15, fontWeight: 600, color: C.text, ...agate, marginTop: 1 }}>{v}</div>
        </div>
      ))}
    </div>
  );
}


// A short, factual player line — composed entirely from data already in the
// model (role, season, headline averages), never fabricated prose. It fills the
// profile's dead space above the stat grid and reads like an agate scouting
// note. Deliberately pronoun-free and terse. College (Wikidata/CC0) slots in
// when present; every clause degrades to nothing if its fact is missing, so a
// bare "Guard for the Dallas Wings." is still a valid line.
const POS_FULL = { G: "Guard", F: "Forward", C: "Center" };
const ordinal = (n) => {
  const s = ["th", "st", "nd", "rd"], v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
};
function PlayerBlurb({ p }) {
  const b = p.bio || {};
  const role = b.posFull || POS_FULL[p.pos] || p.pos;
  let s1 = `${role} for the ${p.team.name}`;
  if (b.college) s1 += `, out of ${b.college}`;
  s1 += ".";

  const season = b.exp === 0 ? "Rookie season" : b.exp != null ? `${ordinal(b.exp + 1)} season` : null;
  const line = `averaging ${p.ppg} points, ${p.rpg} rebounds and ${p.apg} assists across ${p.gp} game${p.gp === 1 ? "" : "s"}.`;
  const s2 = season ? `${season} — ${line}` : line.charAt(0).toUpperCase() + line.slice(1);

  return (
    <p style={{ fontSize: 12, lineHeight: 1.55, color: C.sec, padding: "10px 0", margin: 0, borderBottom: `1px solid ${C.border}` }}>
      <span style={{ color: C.text }}>{s1}</span> <span style={agate}>{s2}</span>
    </p>
  );
}

// Home venue(s) and attendance, both derived from dim_games. The alternate-venue
// line matters more than it looks: Toronto play a touring slate across four
// arenas in three cities, which a single "home arena" field would silently hide.
function TeamBio({ team }) {
  const b = team.bio || {};
  if (!b.arena) return null;
  return (
    <>
      <SectionHead action="derived from fixtures">Home</SectionHead>
      <div style={{ padding: "9px 0", borderBottom: `1px solid ${C.border}` }}>
        <div style={{ fontFamily: DISPLAY, fontSize: 15, fontWeight: 600, color: C.text, letterSpacing: .3 }}>{b.arena}</div>
        <div style={{ fontSize: 11, color: C.sec, marginTop: 1 }}>{b.city} · {b.home} home games</div>
      </div>
      {b.alt?.length > 0 && (
        <div style={{ padding: "8px 0", borderBottom: `1px solid ${C.border}` }}>
          <div style={{ fontSize: 8.5, letterSpacing: .9, textTransform: "uppercase", color: C.sec, fontWeight: 700, marginBottom: 4 }}>Also hosts at</div>
          {b.alt.map(v => (
            <div key={v.n} style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, padding: "2px 0", color: C.text }}>
              <span>{v.n} <span style={{ color: C.mute }}>· {v.c}</span></span>
              <span style={{ color: C.sec, ...agate }}>{v.g}</span>
            </div>
          ))}
        </div>
      )}
      {b.att && (
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", padding: "9px 0", borderBottom: `1px solid ${C.border}` }}>
          <span style={{ fontSize: 11.5, color: C.sec }}>Average attendance</span>
          <span><b style={{ fontFamily: DISPLAY, fontSize: 17, ...agate }}>{b.att.toLocaleString()}</b>
            <span style={{ fontSize: 9.5, color: C.mute, marginLeft: 5 }}>{b.attN} games</span></span>
        </div>
      )}
    </>
  );
}

// A team's season is two different questions wearing one coat: "how have they
// been going?" (newest first) and "what's next?" (soonest first). One
// chronological list answers neither well — you land in May and scroll past two
// months of history to find tonight. Split the sort, keep the data.
function TeamSeason({ team }) {
  const all = useMemo(() => {
    const gs = GAMES.filter(g => g.homeId === team.id || g.awayId === team.id)
      .sort((a, b) => a.date.localeCompare(b.date));
    let w = 0, l = 0;
    return gs.map(g => {
      const isHome = g.homeId === team.id;
      const us = isHome ? g.hs : g.as, them = isHome ? g.as : g.hs;
      const won = g.done && us > them;
      if (g.done) (won ? w++ : l++);
      return { g, isHome, us, them, won, opp: isHome ? g.away : g.home,
               rec: g.done ? `${w}-${l}` : null, margin: g.done ? us - them : null };
    });
  }, [team.id]);

  const results  = useMemo(() => all.filter(r => r.g.done).slice().reverse(), [all]); // newest first
  const fixtures = useMemo(() => all.filter(r => !r.g.done), [all]);                   // soonest first
  const [view, setView] = useState(results.length ? "Results" : "Fixtures");
  const rows = view === "Results" ? results : fixtures;

  // Form: last 10, oldest->newest left to right, the way every league table prints it.
  const form = all.filter(r => r.g.done).slice(-10);

  const months = useMemo(() => {
    const m = [];
    rows.forEach(r => {
      const k = new Date(r.g.date + "T12:00:00").toLocaleDateString("en-US", { month: "long" });
      if (!m.length || m[m.length - 1][0] !== k) m.push([k, []]);
      m[m.length - 1][1].push(r);
    });
    return m;
  }, [rows]);

  return (
    <>
      <div style={{ display: "flex", gap: 0, margin: "10px 0 2px", border: `1px solid ${C.border}`, borderRadius: 3, overflow: "hidden" }}>
        {[["Results", results.length], ["Fixtures", fixtures.length]].map(([v, n]) => (
          <button key={v} onClick={() => setView(v)} style={{
            flex: 1, border: "none", padding: "7px 0", fontSize: 11, fontWeight: 700, letterSpacing: .8,
            textTransform: "uppercase", cursor: "pointer", fontFamily: BODY,
            background: view === v ? C.rule : C.visual, color: view === v ? C.onRule : C.sec,
          }}>{v} <span style={{ opacity: .6, fontWeight: 500 }}>{n}</span></button>
        ))}
      </div>

      {view === "Results" && form.length > 0 && (
        <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "9px 0", borderBottom: `1px solid ${C.border}` }}>
          <span style={{ fontSize: 8.5, letterSpacing: .9, textTransform: "uppercase", color: C.sec, fontWeight: 700 }}>Last {form.length}</span>
          <div style={{ display: "flex", gap: 3, flex: 1 }}>
            {form.map(r => (
              <span key={r.g.id} title={`${r.won ? "W" : "L"} ${r.us}-${r.them}`} style={{
                flex: 1, height: 15, background: r.won ? C.good : C.bad, opacity: .18 + Math.min(Math.abs(r.margin), 20) / 20 * .82,
                borderRadius: 1,
              }} />
            ))}
          </div>
          <span style={{ fontSize: 9, color: C.mute }}>opacity = margin</span>
        </div>
      )}

      {months.map(([month, gs]) => (
        <div key={month + gs[0].g.id}>
          <div style={{ fontSize: 9.5, fontWeight: 700, letterSpacing: 1.2, textTransform: "uppercase", color: C.sec, padding: "11px 0 4px", borderBottom: `1.5px solid ${C.rule}` }}>{month}</div>
          {gs.map(({ g, isHome, us, them, won, opp, rec, margin }) => (
            <div key={g.id} style={{ display: "flex", alignItems: "center", gap: 7, padding: "8px 0", borderBottom: `1px solid ${C.border}` }}>
              <span style={{ fontSize: 10, color: C.mute, width: 20, textAlign: "right", ...agate }}>
                {new Date(g.date + "T12:00:00").getDate()}
              </span>
              <span style={{ fontSize: 9.5, color: C.mute, width: 13 }}>{isHome ? "vs" : "@"}</span>
              <Crest team={opp} size={19} />
              <span style={{ flex: 1, fontSize: 11.5, color: C.text }}>{opp.abbr}</span>
              {g.done ? (
                <>
                  <span style={{ fontSize: 10, fontWeight: 700, color: won ? C.good : C.bad, width: 11 }}>{won ? "W" : "L"}</span>
                  <span style={{ fontFamily: DISPLAY, fontSize: 13, fontWeight: 600, width: 46, textAlign: "right", ...agate }}>{us}–{them}</span>
                  <span style={{ fontSize: 9, color: C.mute, width: 28, textAlign: "right", ...agate }}>{rec}</span>
                </>
              ) : (
                <>
                  <span style={{ fontSize: 9.5, color: C.mute, width: 46, textAlign: "right", ...agate }}>
                    {new Date(g.date + "T12:00:00").toLocaleDateString("en-US", { weekday: "short" })}
                  </span>
                  <span style={{ fontSize: 8.5, color: g.tier === "N" ? C.accent : C.mute, fontWeight: 700, textTransform: "uppercase", width: 62, textAlign: "right" }}>
                    {g.net.replace("WNBA ", "")}
                  </span>
                </>
              )}
            </div>
          ))}
        </div>
      ))}
      {!rows.length && <div style={{ padding: 30, textAlign: "center", fontSize: 12, color: C.sec }}>
        {view === "Results" ? "No games played yet." : "Season complete — no fixtures left."}
      </div>}
    </>
  );
}


// ---- CAREER ARC (player, season-by-season) ----------------------------------
// A points-per-game trajectory (the "arc") over a career, plus the exact numbers
// in an agate table. Data lands from the historical backfill; until then every
// history view degrades to an explicit "not yet". The 2020 Bradenton bubble is
// flagged so a 22-game year isn't misread as a full season.
function CareerArc({ p }) {
  const prior = p.hist || [];
  if (!prior.length) return (
    <div style={{ padding: "34px 10px", textAlign: "center" }}>
      <div style={{ fontFamily: DISPLAY, fontSize: 14, letterSpacing: 1, textTransform: "uppercase", color: C.sec }}>No career history yet</div>
      <div style={{ fontSize: 11.5, color: C.mute, marginTop: 6, lineHeight: 1.6 }}>Season-by-season history lands once the historical backfill runs.</div>
    </div>
  );
  // Append the live current season so the arc's last point is always today's
  // numbers (build_data stores only completed past seasons).
  const CUR = RAW.meta.season || (RAW.meta.lastGame ? +String(RAW.meta.lastGame).slice(0, 4) : 0);
  const h = CUR ? [...prior, { yr: CUR, tm: p.team.abbr, gp: p.gp, ppg: p.ppg, rpg: p.rpg, apg: p.apg, ts: p.ts }] : prior;
  const vals = h.map(s => s.ppg);
  const lo = Math.min(...vals), hi = Math.max(...vals), pad = Math.max((hi - lo) * 0.2, 2);
  const yMin = Math.max(0, lo - pad), yMax = hi + pad;
  const W = 300, H = 96, mL = 13, mR = 13, mT = 16, mB = 15;
  const X = i => mL + (W - mL - mR) * (h.length < 2 ? 0.5 : i / (h.length - 1));
  const Y = v => mT + (H - mT - mB) * (1 - (v - yMin) / (yMax - yMin || 1));
  const pts = h.map((s, i) => [X(i), Y(s.ppg)]);
  const line = "M " + pts.map(pt => pt.map(n => n.toFixed(1)).join(" ")).join(" L ");
  const area = line + ` L ${pts[pts.length - 1][0].toFixed(1)} ${H - mB} L ${pts[0][0].toFixed(1)} ${H - mB} Z`;
  const best = h.reduce((a, b) => b.ppg > a.ppg ? b : a);
  return (
    <>
      <SectionHead action="PPG by season">Career arc</SectionHead>
      <svg viewBox={`0 0 ${W} ${H}`} style={{ width: "100%", display: "block", marginTop: 4 }} role="img" aria-label={`${p.name} points per game by season`}>
        <path d={area} fill={C.blue} fillOpacity={0.08} />
        <path d={line} fill="none" stroke={C.blue} strokeWidth={1.6} strokeLinejoin="round" strokeLinecap="round" />
        {pts.map(([x, y], i) => {
          // Keep the end labels from clipping: anchor the first to its start, the
          // last to its end, the rest centred.
          const anchor = i === 0 ? "start" : i === pts.length - 1 ? "end" : "middle";
          return (
            <g key={i}>
              <circle cx={x} cy={y} r={2.4} fill={h[i].yr === best.yr ? C.accent : C.blue} />
              <text x={x} y={y - 4.5} textAnchor={anchor} style={{ fontFamily: DISPLAY, fontSize: 8, fontWeight: 600, fill: C.text, fontVariantNumeric: "tabular-nums" }}>{h[i].ppg}</text>
              <text x={x} y={H - 4} textAnchor={anchor} style={{ fontSize: 6.5, fill: C.mute, fontVariantNumeric: "tabular-nums" }}>{String(h[i].yr).slice(2)}{h[i].bubble ? "*" : ""}</text>
            </g>
          );
        })}
      </svg>
      <div style={{ display: "flex", borderTop: `1px solid ${C.border}`, borderBottom: `1px solid ${C.border}`, marginTop: 6 }}>
        {[["Seasons", h.length], ["Career high", best.ppg], ["Best year", best.yr]].map(([k, v], i) => (
          <div key={k} style={{ flex: 1, padding: "8px 10px", borderRight: i < 2 ? `1px solid ${C.border}` : "none" }}>
            <div style={{ fontSize: 8, letterSpacing: .8, textTransform: "uppercase", color: C.sec, fontWeight: 700 }}>{k}</div>
            <div style={{ fontFamily: DISPLAY, fontSize: 16, fontWeight: 600, color: C.text, ...agate }}>{v}</div>
          </div>
        ))}
      </div>
      <SectionHead action="per game">By season</SectionHead>
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead><tr>
          <th style={{ ...thStyle, textAlign: "left" }}>Season</th>
          <th style={{ ...thStyle, textAlign: "left" }}>Tm</th>
          {["GP", "PPG", "RPG", "APG", "TS%"].map(l => <th key={l} style={thStyle}>{l}</th>)}
        </tr></thead>
        <tbody>
          {h.slice().reverse().map((s, i) => (
            <tr key={s.yr} style={{ background: i % 2 ? C.stripe : "transparent", borderBottom: `1px solid ${C.border}` }}>
              <td style={{ ...tdStyle, textAlign: "left" }}>{s.yr}{s.bubble ? <span style={{ color: C.accent }}> *</span> : ""}</td>
              <td style={{ ...tdStyle, textAlign: "left", color: C.sec }}>{s.tm}</td>
              <td style={tdStyle}>{s.gp}</td>
              <td style={{ ...tdStyle, fontWeight: s.yr === best.yr ? 700 : 400 }}>{s.ppg}</td>
              <td style={tdStyle}>{s.rpg}</td><td style={tdStyle}>{s.apg}</td><td style={tdStyle}>{s.ts}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {h.some(s => s.bubble) && (
        <div style={{ fontSize: 9, color: C.mute, paddingTop: 7, lineHeight: 1.5 }}>
          <span style={{ color: C.accent, fontWeight: 700 }}>*</span> 2020 was the 22-game Bradenton “bubble” season — a shortened schedule, flagged so it isn’t read as a full year.
        </div>
      )}
    </>
  );
}

// ---- TEAM HISTORY (season-by-season) ----------------------------------------
function TeamHistory({ team }) {
  const prior = team.hist || [];
  if (!prior.length) return (
    <div style={{ padding: "34px 10px", textAlign: "center" }}>
      <div style={{ fontFamily: DISPLAY, fontSize: 14, letterSpacing: 1, textTransform: "uppercase", color: C.sec }}>No season history yet</div>
      <div style={{ fontSize: 11.5, color: C.mute, marginTop: 6, lineHeight: 1.6 }}>Past seasons appear once the historical backfill runs.</div>
    </div>
  );
  // Append the live current season from the standings so the timeline ends on today.
  const CUR = RAW.meta.season || (RAW.meta.lastGame ? +String(RAW.meta.lastGame).slice(0, 4) : 0);
  const st = STANDINGS.find(x => x.id === team.id);
  const h = (CUR && st) ? [...prior, { yr: CUR, w: st.w, l: st.l, pct: st.pct, pf: st.pf, pa: st.pa, note: "" }] : prior;
  const maxPct = Math.max(...h.map(s => s.pct), 0.5);
  return (
    <>
      <SectionHead action="win % by season">Season history</SectionHead>
      <div style={{ display: "flex", alignItems: "flex-end", gap: 6, height: 100, padding: "10px 2px 0", borderBottom: `1px solid ${C.border}` }}>
        {h.map(s => (
          <div key={s.yr} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "flex-end", height: "100%" }}>
            <span style={{ fontFamily: DISPLAY, fontSize: 8.5, fontWeight: 600, color: C.text, ...agate }}>{s.w}–{s.l}</span>
            <div style={{ width: "70%", background: team.color, height: `${(s.pct / maxPct) * 82}%`, minHeight: 2, marginTop: 2, borderRadius: "1px 1px 0 0" }} />
            <span style={{ fontSize: 7, color: C.mute, marginTop: 3, ...agate }}>{String(s.yr).slice(2)}{s.bubble ? "*" : ""}</span>
          </div>
        ))}
      </div>
      <SectionHead action="regular season">By season</SectionHead>
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead><tr>
          <th style={{ ...thStyle, textAlign: "left" }}>Season</th>
          <th style={thStyle}>W–L</th><th style={thStyle}>PCT</th><th style={thStyle}>PF</th><th style={thStyle}>PA</th>
          <th style={{ ...thStyle, textAlign: "right" }}>Result</th>
        </tr></thead>
        <tbody>
          {h.slice().reverse().map((s, i) => (
            <tr key={s.yr} style={{ background: i % 2 ? C.stripe : "transparent", borderBottom: `1px solid ${C.border}` }}>
              <td style={{ ...tdStyle, textAlign: "left" }}>{s.yr}{s.bubble ? <span style={{ color: C.accent }}> *</span> : ""}</td>
              <td style={{ ...tdStyle, fontWeight: 700 }}>{s.w}–{s.l}</td>
              <td style={tdStyle}>{s.pct.toFixed(3).replace(/^0/, "")}</td>
              <td style={tdStyle}>{s.pf}</td><td style={tdStyle}>{s.pa}</td>
              <td style={{ ...tdStyle, color: s.note ? C.text : C.mute, fontWeight: s.note && /Champ/i.test(s.note) ? 700 : 400 }}>{s.note || "—"}</td>
            </tr>
          ))}
        </tbody>
      </table>
      {h.some(s => s.bubble) && (
        <div style={{ fontSize: 9, color: C.mute, paddingTop: 7, lineHeight: 1.5 }}>
          <span style={{ color: C.accent, fontWeight: 700 }}>*</span> 2020 was the 22-game Bradenton “bubble” season.
        </div>
      )}
    </>
  );
}

// ---- SHOT FINGERPRINT -------------------------------------------------------
// Zones are spatial, so they're drawn on a court, not a radar. A radar's spoke
// order is arbitrary — reorder the axes and the same player gets a different
// silhouette, which is fatal for something whose whole claim is "this shape is
// this player". The floor is the honest projection of floor data.
//
// Labels live ON the court. The hard part is that zone areas differ ~10x: the
// corner is a 3ft sliver and above-the-break is the whole width. Solved by
// rotating the corner label 90deg so its length runs down the corner's 7.8ft
// height rather than across its 3ft width. Every label position below was
// checked against the zone's actual free space, not eyeballed.
const CW = 50, CD = 35, HOOP_Y = 5.25, ARC_R = 22.15, RA_R = 4, CORNER_X = 3;
const sy = (courtY) => CD - courtY;
const CORNER_MEET = HOOP_Y + Math.sqrt(ARC_R ** 2 - (CW / 2 - CORNER_X) ** 2); // 7.82
const ARC_APEX = HOOP_Y + ARC_R;                                               // 27.40

function arcPath() {
  // Snap the ends to exactly where the corner lines meet the arc — sampling
  // alone leaves a visible ~1ft gap at each corner.
  const pts = [[CORNER_X, sy(CORNER_MEET)]];
  for (let i = 0; i <= 90; i++) {
    const a = Math.PI * (i / 90);
    const x = CW / 2 - ARC_R * Math.cos(a);
    const y = HOOP_Y + ARC_R * Math.sin(a);
    if (y >= CORNER_MEET) pts.push([x, sy(y)]);
  }
  pts.push([CW - CORNER_X, sy(CORNER_MEET)]);
  return pts;
}
const ARC_D = "M " + arcPath().map(([x, y]) => `${x.toFixed(2)} ${y.toFixed(2)}`).join(" L ");

// The shot chart is a data visualisation, not an app surface: its zone fills
// encode frequency/accuracy and were tuned for a light "chalk court". Theming it
// dark muddies those low-opacity fills and — worse — turns the labels near-white
// against a white halo, so they vanish. So the court renders with the LIGHT
// palette in BOTH modes (same as light mode); only the surrounding UI themes.
const COURT = LIGHT;

// White halo behind glyphs via paint-order, so a label stays legible whether
// its zone is near-white or fully saturated.
const HALO = { stroke: "#FFFFFF", strokeWidth: 0.85, paintOrder: "stroke", strokeLinejoin: "round" };

function ZoneLabel({ x, y, name, value, delta, mode }) {
  if (value == null) return null;
  const dc = delta == null ? COURT.mute : delta > 0 ? COURT.good : COURT.bad;
  return (
    <g transform={`translate(${x} ${y})`}>
      <text textAnchor="middle" y={0} {...HALO}
        style={{ fontSize: 1.45, fontWeight: 700, letterSpacing: 0.12, fill: COURT.sec }}>
        {name}
      </text>
      <text textAnchor="middle" y={2.9} {...HALO}
        style={{ fontFamily: DISPLAY, fontSize: 2.9, fontWeight: 700, fill: COURT.text }}>
        {value.toFixed(1)}%
      </text>
      {mode === "eff" && delta != null && (
        <text textAnchor="middle" y={5} {...HALO}
          style={{ fontSize: 1.5, fontWeight: 700, fill: dc }}>
          {delta > 0 ? "+" : ""}{delta.toFixed(1)} vs lg
        </text>
      )}
    </g>
  );
}

function ShotFingerprint({ p }) {
  const [mode, setMode] = useState("freq");
  const d = SHOTS.P[String(p.id)] || SHOTS.P[p.id];

  if (!d) return (
    <div style={{ padding: "34px 10px", textAlign: "center" }}>
      <div style={{ fontFamily: DISPLAY, fontSize: 14, letterSpacing: 1, textTransform: "uppercase", color: C.sec }}>Not enough shots</div>
      <div style={{ fontSize: 11.5, color: C.mute, marginTop: 6, lineHeight: 1.6 }}>
        A fingerprint needs 60+ field goal attempts.<br />Below that, a five-way split is noise, not a profile.
      </div>
    </div>
  );

  const maxF = Math.max(...d.f);
  const tone = (i) => {
    if (mode === "freq") return { c: COURT.accent, o: 0.07 + (d.f[i] / maxF) * 0.6 };
    if (d.p[i] == null) return { c: COURT.mute, o: 0.08 };
    const delta = d.p[i] - SHOTS.LG.fg[i];
    return { c: delta >= 0 ? COURT.good : COURT.bad, o: 0.09 + Math.min(Math.abs(delta) / 15, 1) * 0.58 };
  };
  const val = (i) => (mode === "freq" ? d.f[i] : d.p[i]);
  const dlt = (i) => (d.p[i] == null ? null : d.p[i] - SHOTS.LG.fg[i]);

  return (
    <>
      <div style={{ display: "flex", margin: "10px 0 8px", border: `1px solid ${C.border}`, borderRadius: 3, overflow: "hidden" }}>
        {[["freq", "Shot diet"], ["eff", "Accuracy vs league"]].map(([k, l]) => (
          <button key={k} onClick={() => setMode(k)} style={{
            flex: 1, border: "none", padding: "7px 0", fontSize: 11, fontWeight: 700, letterSpacing: .7,
            textTransform: "uppercase", cursor: "pointer", fontFamily: BODY,
            background: mode === k ? C.rule : C.visual, color: mode === k ? C.onRule : C.sec,
          }}>{l}</button>
        ))}
      </div>

      <svg viewBox={`-0.5 -0.5 ${CW + 1} ${CD + 1}`} role="img"
           aria-label={`Shot zone map for ${p.name}`}
           style={{ width: "100%", display: "block", background: COURT.visual, border: `1px solid ${COURT.border}` }}>
        {/* fills painted back to front — overlap does the clipping */}
        <rect x={0} y={0} width={CW} height={CD} fill={tone(4).c} fillOpacity={tone(4).o} />
        <rect x={0} y={sy(CORNER_MEET)} width={CORNER_X} height={CORNER_MEET} fill={tone(3).c} fillOpacity={tone(3).o} />
        <rect x={CW - CORNER_X} y={sy(CORNER_MEET)} width={CORNER_X} height={CORNER_MEET} fill={tone(3).c} fillOpacity={tone(3).o} />
        <path d={`${ARC_D} L ${CW - CORNER_X} ${CD} L ${CORNER_X} ${CD} Z`} fill={tone(2).c} fillOpacity={tone(2).o} />
        <rect x={CW / 2 - 8} y={sy(19)} width={16} height={19} fill={tone(1).c} fillOpacity={tone(1).o} />
        <path d={`M ${CW / 2 - RA_R} ${CD} L ${CW / 2 - RA_R} ${sy(HOOP_Y)} A ${RA_R} ${RA_R} 0 0 1 ${CW / 2 + RA_R} ${sy(HOOP_Y)} L ${CW / 2 + RA_R} ${CD} Z`}
              fill={tone(0).c} fillOpacity={tone(0).o} />

        {/* court markings */}
        <g fill="none" stroke={COURT.text} strokeWidth={0.2} strokeOpacity={0.55} strokeLinejoin="round">
          <rect x={0} y={0} width={CW} height={CD} strokeOpacity={0.3} />
          <rect x={CW / 2 - 8} y={sy(19)} width={16} height={19} />
          <path d={`M ${CW / 2 - 6} ${sy(19)} A 6 6 0 0 1 ${CW / 2 + 6} ${sy(19)}`} />
          <path d={ARC_D} />
          <line x1={CORNER_X} y1={CD} x2={CORNER_X} y2={sy(CORNER_MEET)} />
          <line x1={CW - CORNER_X} y1={CD} x2={CW - CORNER_X} y2={sy(CORNER_MEET)} />
          <path d={`M ${CW / 2 - RA_R} ${sy(HOOP_Y)} A ${RA_R} ${RA_R} 0 0 1 ${CW / 2 + RA_R} ${sy(HOOP_Y)}`} strokeOpacity={0.35} />
        </g>
        <line x1={CW / 2 - 3} y1={sy(4)} x2={CW / 2 + 3} y2={sy(4)} stroke={COURT.text} strokeWidth={0.4} strokeOpacity={0.7} />
        <circle cx={CW / 2} cy={sy(HOOP_Y)} r={0.7} fill="none" stroke={COURT.accent} strokeWidth={0.38} />

        {/* labels — positions checked against each zone's real free space */}
        <ZoneLabel x={CW / 2} y={sy(3.3)} name="RIM"       value={val(0)} delta={dlt(0)} mode="freq" />
        <ZoneLabel x={CW / 2} y={sy(15.4)} name="PAINT"     value={val(1)} delta={dlt(1)} mode={mode} />
        <ZoneLabel x={CW / 2} y={sy(24.2)} name="MID-RANGE" value={val(2)} delta={dlt(2)} mode={mode} />
        <ZoneLabel x={CW / 2} y={sy(32.4)} name="ABOVE THE BREAK" value={val(4)} delta={dlt(4)} mode={mode} />
        {/* Corner: ONE label, single rotated line. Both corners are one combined
            zone, so a second figure would only invite the reader to think they
            differ. Two stacked lines can't work rotated — they'd spread across
            the corner's 3ft width instead of down its 7.8ft height, which is
            what pushed the right-hand label off the canvas. */}
        {val(3) != null && (
          <text x={CORNER_X / 2} y={sy(4.0)} textAnchor="middle"
                transform={`rotate(-90 ${CORNER_X / 2} ${sy(4.0)})`} {...HALO}
                style={{ fontFamily: DISPLAY, fontSize: 2.4, fontWeight: 700, fill: COURT.text }}>
            {val(3).toFixed(1)}%
          </text>
        )}
        {/* rim delta sits beside the arc rather than under it — no room below */}
        {mode === "eff" && dlt(0) != null && (
          <text x={CW / 2} y={sy(10.6)} textAnchor="middle" {...HALO}
                style={{ fontSize: 1.5, fontWeight: 700, fill: dlt(0) > 0 ? COURT.good : COURT.bad }}>
            {dlt(0) > 0 ? "+" : ""}{dlt(0).toFixed(1)} vs lg
          </text>
        )}
      </svg>

      <div style={{ display: "flex", justifyContent: "space-between", gap: 10, fontSize: 9, color: C.mute, padding: "7px 0 0", lineHeight: 1.5 }}>
        <span>
          {mode === "freq"
            ? `Share of ${d.n} field goal attempts. Free throws excluded. Darker = more shots.`
            : `Field goal % by zone. Green beats the league in that zone, red trails it.`}
        </span>
        <span style={{ whiteSpace: "nowrap", ...agate }}>{d.n} FGA</span>
      </div>
      <div style={{ fontSize: 9, color: C.mute, paddingTop: 3, lineHeight: 1.5 }}>
        The rotated figure in the corner is <b style={{ color: C.text }}>Corner 3</b> — both corners combined, which is why only one is marked. Attempts by zone:{" "}
        {["rim", "paint", "mid", "corner", "above"].map((z, i) => `${z} ${d.a[i]}`).join(" · ")}.
        {d.p.some(x => x == null) && " Zones under 8 attempts are greyed — too few to judge."}
      </div>

      {d.c && <>
        <SectionHead action="vs league">How the shots come</SectionHead>
        {[["spot", "Catch & shoot"], ["drive", "Driving"], ["offdrib", "Off the dribble"],
          ["cut", "Cutting"], ["post", "Post up / turnaround"], ["putback", "Putback"]].map(([k, l], i) => {
          const v = d.c[i], lg = SHOTS.LG.create[i], delta = v - lg;
          return (
            <div key={k} style={{ padding: "8px 0", borderBottom: `1px solid ${C.border}` }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 3 }}>
                <span style={{ fontSize: 11.5, color: C.sec }}>{l}</span>
                <span style={{ ...agate, fontSize: 11.5 }}>
                  <b>{v.toFixed(1)}%</b>
                  <span style={{ color: Math.abs(delta) < 3 ? C.mute : delta > 0 ? C.good : C.bad, marginLeft: 6, fontWeight: 700 }}>
                    {delta >= 0 ? "+" : ""}{delta.toFixed(1)}
                  </span>
                </span>
              </div>
              <div style={{ height: 6, background: C.border, position: "relative" }}>
                <div style={{ height: "100%", width: `${Math.min(v / 50 * 100, 100)}%`, background: C.blue }} />
                {/* league tick — the bar without it is just the number written twice */}
                <div style={{ position: "absolute", left: `${Math.min(lg / 50 * 100, 100)}%`, top: -2, bottom: -2, width: 1.5, background: C.rule }} />
              </div>
            </div>
          );
        })}
        <div style={{ fontSize: 9, color: C.mute, paddingTop: 7, lineHeight: 1.5 }}>
          Tick marks the league average. Derived from play type — a “driving layup” counts as driving, a “step back jump shot” as off the dribble.
        </div>
      </>}
    </>
  );
}

function TabBar({ tab, setTab }) {
  const items = [["home", Home, "Today"], ["teams", Shield, "Teams"], ["players", Users, "Players"], ["schedule", CalendarDays, "Schedule"], ["more", MoreHorizontal, "About"]];
  return (
    <div style={{ display: "flex", borderTop: `1px solid ${C.border}`, background: C.visual, padding: "6px 0 12px", flexShrink: 0 }}>
      {items.map(([k, Icon, label]) => (
        <button key={k} onClick={() => setTab(k)} style={{ flex: 1, border: "none", background: "none", display: "flex", flexDirection: "column", alignItems: "center", gap: 3, padding: "3px 0", cursor: "pointer" }}>
          <Icon size={19} color={tab === k ? C.accent : C.mute} strokeWidth={tab === k ? 2.4 : 1.7} />
          <span style={{ fontSize: 9, fontWeight: tab === k ? 700 : 500, color: tab === k ? C.accent : C.mute, letterSpacing: .4 }}>{label}</span>
        </button>
      ))}
    </div>
  );
}
